"""Arena Loot Treasury v3: no subscription, purchase method or fixed DARK pool.

The game server reserves new rewards in Firebase. A reusable global counter
prevents duplicate direct payouts. Existing v2 claim budgets remain protected. Randomness
is generated by the game server, NOT purported to be a trustless on-chain VRF.
Creation args: oracle public key (32 bytes). AVM v9 resource/budget pooling.
"""
from pathlib import Path
from pyteal import *

DEPLOYMENT_SCHEMA={'localInts':0,'localBytes':0,'globalInts':2,'globalBytes':1}
DEPLOYMENT_CREATE_ARGS='oracle'
TEAL_VERSION=9
DEPLOYMENT_ASSEMBLE_CONSTANTS=True

def clear_state_program():
    return Approve()

def approval_program():
    zero=Global.zero_address()
    loader=Addr('VWYCYQ3H3PPNIGON4H363DIH7BP33TTZWUUUNMTDXCIHRCDPFOMU7VJ5HM')
    oracle,paused=Bytes('oracle'),Bytes('paused')
    safe=And(Txn.rekey_to()==zero,Txn.on_completion()==OnComplete.NoOp)
    # Updating code is an explicit creator power; the game oracle cannot upgrade.
    upgrade=Seq(Assert(And(Txn.sender()==Global.creator_address(),Txn.rekey_to()==zero)),Approve())
    @Subroutine(TealType.none)
    def transfer(asset,receiver,amount):
        return Seq(InnerTxnBuilder.Begin(),InnerTxnBuilder.SetFields({TxnField.type_enum:TxnType.AssetTransfer,TxnField.xfer_asset:asset,TxnField.asset_receiver:receiver,TxnField.asset_amount:amount,TxnField.fee:Int(0)}),InnerTxnBuilder.Submit())
    @Subroutine(TealType.none)
    def funding(amount):
        return Assert(And(Gtxn[0].type_enum()==TxnType.Payment,Gtxn[0].sender()==Txn.sender(),Gtxn[0].receiver()==Global.current_application_address(),Gtxn[0].amount()==amount,Gtxn[0].rekey_to()==zero,Gtxn[0].close_remainder_to()==zero))
    create=Seq(Assert(And(Txn.application_args.length()==Int(1),Len(Txn.application_args[0])==Int(32),Txn.rekey_to()==zero)),App.globalPut(oracle,Txn.application_args[0]),App.globalPut(paused,Int(1)),App.globalPut(Bytes('version'),Int(3)),Approve())
    # v3 packs a monotonic payout sequence above bit zero of paused, reusing
    # the existing global schema. Admin pause changes never reset that sequence.
    pause=Seq(Assert(Txn.sender()==Global.creator_address()),Assert(Btoi(Txn.application_args[1])<=Int(1)),App.globalPut(paused,BitwiseOr(BitwiseAnd(App.globalGet(paused),Int(18446744073709551614)),Btoi(Txn.application_args[1]))),Approve())
    rotate=Seq(Assert(Txn.sender()==Global.creator_address()),Assert(Len(Txn.application_args[1])==Int(32)),App.globalPut(oracle,Txn.application_args[1]),Approve())

    # New rewards use no encounter/budget boxes. The authorized server maintains
    # reservations off chain; old on-chain reservations remain protected.
    activate_direct=Seq(Assert(And(Txn.sender()==Global.creator_address(),App.globalGet(Bytes('version'))==Int(2))),App.globalPut(Bytes('version'),Int(3)),Approve())
    sequence=Btoi(Txn.application_args[1])
    next_sequence=Seq(Assert(And(sequence==ShiftRight(App.globalGet(paused),Int(1)),sequence<Int(9223372036854775807))),App.globalPut(paused,App.globalGet(paused)+Int(2)))
    direct_asset=Btoi(Txn.application_args[2]);direct_qty=Btoi(Txn.application_args[3])
    direct_box=App.box_get(Concat(Bytes('a'),Itob(direct_asset)))
    direct_holding=AssetHolding.balance(Global.current_application_address(),direct_asset)
    direct_recipient=AssetHolding.balance(Txn.accounts[1],direct_asset)
    pay_direct=Seq(
        Assert(And(App.globalGet(Bytes('version'))==Int(3),Txn.sender()==App.globalGet(oracle),BitwiseAnd(App.globalGet(paused),Int(1))==Int(0),Txn.application_args.length()==Int(4),Txn.accounts.length()==Int(1),direct_qty>Int(0))),
        direct_box,direct_holding,direct_recipient,
        Assert(And(direct_box.hasValue(),direct_holding.hasValue(),direct_recipient.hasValue())),
        Assert(And(direct_holding.value()>=Btoi(Extract(direct_box.value(),Int(0),Int(8))),direct_qty<=direct_holding.value()-Btoi(Extract(direct_box.value(),Int(0),Int(8))))),
        next_sequence,
        InnerTxnBuilder.Begin(),InnerTxnBuilder.SetFields({TxnField.type_enum:TxnType.AssetTransfer,TxnField.xfer_asset:direct_asset,TxnField.asset_receiver:Txn.accounts[1],TxnField.asset_amount:direct_qty,TxnField.fee:Global.min_txn_fee()}),InnerTxnBuilder.Submit(),Approve())
    # A serialized, replay-safe 10 ALGO refill, only below 1 spendable ALGO.
    refill=Seq(Assert(And(App.globalGet(Bytes('version'))==Int(3),Txn.sender()==Global.creator_address(),Txn.sender()==App.globalGet(oracle),Txn.group_index()>Int(0))),
        Assert(And(Gtxn[Txn.group_index()-Int(1)].type_enum()==TxnType.Payment,Gtxn[Txn.group_index()-Int(1)].sender()==Txn.sender(),Gtxn[Txn.group_index()-Int(1)].receiver()==Global.current_application_address(),Gtxn[Txn.group_index()-Int(1)].amount()==Int(10000000),Gtxn[Txn.group_index()-Int(1)].rekey_to()==zero,Gtxn[Txn.group_index()-Int(1)].close_remainder_to()==zero)),
        Assert(Balance(Global.current_application_address())-Int(10000000)<MinBalance(Global.current_application_address())+Int(1000000)),next_sequence,Approve())

    # a+ASA: reserved uint64, kind (0 token / 1 NFT), max event basis points,
    # max event atomic amount (zero means percentage cap only).
    aid=Btoi(Txn.application_args[1]);kind=Btoi(Txn.application_args[2]);bps=Btoi(Txn.application_args[3]);maximum=Btoi(Txn.application_args[4])
    akey=Concat(Bytes('a'),Itob(aid));old=App.box_get(akey);holding=AssetHolding.balance(Global.current_application_address(),aid);total=AssetParam.total(aid);decimals=AssetParam.decimals(aid)
    register=Seq(Assert(Txn.sender()==Global.creator_address()),Assert(And(Global.group_size()==Int(2),Txn.group_index()==Int(1),kind<=Int(1),bps>Int(0),bps<=Int(10000))),old,holding,total,decimals,
        Assert(And(total.hasValue(),decimals.hasValue())),
        If(kind==Int(1)).Then(Assert(And(total.value()==Int(1),decimals.value()==Int(0),maximum==Int(1)))).Else(Assert(Or(total.value()!=Int(1),decimals.value()!=Int(0)))),
        If(old.hasValue()).Then(Assert(Btoi(Extract(old.value(),Int(8),Int(8)))==kind)),
        funding(If(old.hasValue(),Int(0),Int(18900))+If(holding.hasValue(),Int(0),Int(100000))),
        # Even the creator cannot use registration to bypass the loading wallet.
        Assert(Or(holding.hasValue(),Txn.sender()==loader)),
        If(Not(holding.hasValue())).Then(transfer(aid,Global.current_application_address(),Int(0))),
        App.box_put(akey,Concat(If(old.hasValue(),Extract(old.value(),Int(0),Int(8)),Itob(Int(0))),Itob(kind),Itob(bps),Itob(maximum))),Approve())

    modern=App.globalGet(Bytes('version'))==Int(3)
    deposit_index=Global.group_size()-Int(1)
    # Atomic load: ALGO funding -> authorized app call/inner opt-in -> ASA deposit.
    # Existing registration caps and reserved rewards must never be overwritten.
    load_asset=Btoi(Txn.application_args[1]);load_key=Concat(Bytes('a'),Itob(load_asset))
    load_box=App.box_get(load_key);load_holding=AssetHolding.balance(Global.current_application_address(),load_asset)
    load_total=AssetParam.total(load_asset);load_decimals=AssetParam.decimals(load_asset)
    pre_funding=ScratchVar(TealType.uint64);required_balance=ScratchVar(TealType.uint64);is_nft=ScratchVar(TealType.uint64)
    load=Seq(Assert(And(Txn.sender()==loader,Txn.application_args.length()==Int(2),Or(And(Global.group_size()==Int(3),Txn.group_index()==Int(1)),And(modern,Global.group_size()==Int(2),Txn.group_index()==Int(0))))),
        Assert(And(Len(Txn.application_args[1])==Int(8),load_asset>Int(0))),
        Assert(And(Gtxn[deposit_index].type_enum()==TxnType.AssetTransfer,Gtxn[deposit_index].sender()==loader,Gtxn[deposit_index].asset_receiver()==Global.current_application_address(),Gtxn[deposit_index].xfer_asset()==load_asset,Gtxn[deposit_index].asset_amount()>Int(0),Gtxn[deposit_index].asset_sender()==zero,Gtxn[deposit_index].asset_close_to()==zero,Gtxn[deposit_index].rekey_to()==zero)),
        load_box,load_holding,load_total,load_decimals,Assert(And(load_total.hasValue(),load_decimals.hasValue())),
        is_nft.store(And(load_total.value()==Int(1),load_decimals.value()==Int(0))),
        If(load_box.hasValue()).Then(Assert(And(Len(load_box.value())==Int(32),Btoi(Extract(load_box.value(),Int(8),Int(8)))==is_nft.load()))),
        pre_funding.store(Balance(Global.current_application_address())-If(Txn.group_index()==Int(1),Gtxn[0].amount(),Int(0))),
        required_balance.store(If(MinBalance(Global.current_application_address())<Int(100000),Int(100000),MinBalance(Global.current_application_address()))+If(load_box.hasValue(),Int(0),Int(18900))+If(load_holding.hasValue(),Int(0),Int(100000))),
        If(modern).Then(Seq(If(Txn.group_index()==Int(1)).Then(Seq(funding(Int(10000000)),Assert(pre_funding.load()<MinBalance(Global.current_application_address())+Int(1000000)))),Assert(Balance(Global.current_application_address())>=required_balance.load()))).Else(funding(If(required_balance.load()>pre_funding.load(),required_balance.load()-pre_funding.load(),Int(0)))),
        If(Not(load_holding.hasValue())).Then(transfer(load_asset,Global.current_application_address(),Int(0))),
        If(Not(load_box.hasValue())).Then(App.box_put(load_key,Concat(Itob(Int(0)),Itob(is_nft.load()),Itob(Int(10000)),Itob(is_nft.load())))),Approve())

    # Existing e/b boxes are read only by the legacy claim path. No new
    # encounter records or allocations can be published by this program.
    # claim: hour, slot, champion ASA, reward ASA, amount, six sibling hashes.
    chour=Btoi(Txn.application_args[1]);slot=Btoi(Txn.application_args[2]);reward=Btoi(Txn.application_args[4]);qty=Btoi(Txn.application_args[5]);ckey=Concat(Bytes('e'),Itob(chour));cevent=App.box_get(ckey)
    rkey=Concat(Bytes('a'),Itob(reward));rbox=App.box_get(rkey);bkey=Concat(Bytes('b'),Itob(chour),Itob(reward));bbox=App.box_get(bkey)
    bits=ScratchVar(TealType.uint64);digest=ScratchVar(TealType.bytes);j=ScratchVar(TealType.uint64)
    sponsored=Txn.application_args[0]==Bytes('claim_for')
    recipient=If(sponsored,Txn.accounts[1],Txn.sender())
    pickup=Seq(Assert(And(Txn.sender()==App.globalGet(oracle),slot<Int(8))),
        cevent,Assert(cevent.hasValue()),App.box_replace(ckey,Int(32),Itob(BitwiseOr(Btoi(Extract(cevent.value(),Int(32),Int(8))),ShiftLeft(Int(1),slot+Int(8))))),Approve())
    claim=Seq(If(sponsored).Then(Assert(And(Txn.sender()==App.globalGet(oracle),Txn.accounts.length()==Int(1)))),Assert(And(Txn.application_args.length()==Int(12),slot<Int(8),qty>Int(0),Len(Txn.application_args[3])==Int(8))),cevent,rbox,bbox,Assert(And(cevent.hasValue(),rbox.hasValue(),bbox.hasValue())),
        bits.store(Btoi(Extract(cevent.value(),Int(32),Int(8)))),Assert(BitwiseAnd(bits.load(),ShiftLeft(Int(1),slot))==Int(0)),
        Assert(Or(sponsored,BitwiseAnd(bits.load(),ShiftLeft(Int(1),slot+Int(8)))!=Int(0))),
        digest.store(Sha256(Concat(Bytes('DCL2'),Itob(Global.current_application_id()),Itob(chour),Itob(slot),recipient,Txn.application_args[3],Itob(reward),Itob(qty)))),
        For(j.store(Int(0)),j.load()<Int(6),j.store(j.load()+Int(1))).Do(Seq(Assert(Len(Txn.application_args[j.load()+Int(6)])==Int(32)),digest.store(Sha256(If(BitwiseAnd(ShiftRight(slot,j.load()),Int(1))==Int(0),Concat(digest.load(),Txn.application_args[j.load()+Int(6)]),Concat(Txn.application_args[j.load()+Int(6)],digest.load())))))),
        Assert(And(digest.load()==Extract(cevent.value(),Int(0),Int(32)),qty<=Btoi(bbox.value()),qty<=Btoi(Extract(rbox.value(),Int(0),Int(8))))),
        App.box_replace(ckey,Int(32),Itob(BitwiseOr(bits.load(),ShiftLeft(Int(1),slot)))),App.box_put(bkey,Itob(Btoi(bbox.value())-qty)),
        App.box_replace(rkey,Int(0),Itob(Btoi(Extract(rbox.value(),Int(0),Int(8)))-qty)),transfer(reward,recipient,qty),Approve())
    return Cond([Txn.application_id()==Int(0),create],[Txn.on_completion()==OnComplete.UpdateApplication,upgrade],[safe,Cond([Or(App.globalGet(Bytes('version'))==Int(2),App.globalGet(Bytes('version'))==Int(3)),Cond([Txn.application_args[0]==Bytes('activate_direct'),activate_direct],[Txn.application_args[0]==Bytes('pay_direct'),pay_direct],[Txn.application_args[0]==Bytes('refill'),refill],[Txn.application_args[0]==Bytes('budget'),Approve()],[Txn.application_args[0]==Bytes('load'),load],[Txn.application_args[0]==Bytes('register'),register],[Txn.application_args[0]==Bytes('pause'),pause],[Txn.application_args[0]==Bytes('oracle'),rotate],[Txn.application_args[0]==Bytes('pickup'),pickup],[Or(Txn.application_args[0]==Bytes('claim'),sponsored),claim])])])

if __name__=='__main__':
    from compile_contract import write_deployment_programs
    approval=compileTeal(approval_program(),Mode.Application,version=TEAL_VERSION,assembleConstants=DEPLOYMENT_ASSEMBLE_CONSTANTS)
    clear=compileTeal(clear_state_program(),Mode.Application,version=TEAL_VERSION,assembleConstants=DEPLOYMENT_ASSEMBLE_CONSTANTS)
    write_deployment_programs(__file__,approval,clear,{
        'source':Path(__file__).name,'avmVersion':TEAL_VERSION,
        'schema':DEPLOYMENT_SCHEMA,'creationArgs':DEPLOYMENT_CREATE_ARGS})
    # Keep the existing arena tooling's copies in sync with deployment.js.
    out=Path(__file__).resolve().parent/'arena-treasury';out.mkdir(exist_ok=True)
    (out/'approval.teal').write_text(approval)
    (out/'clear.teal').write_text(clear)
    print('Compiled ArenaTreasury.py to approval.teal and clear_state.teal beside deployment.js')
